# bash completion for tess. Generated by `tess completion bash`: run it again after upgrading tess.

# Install: source it from ~/.bashrc, or save it as ~/.local/share/bash-completion/completions/tess.

_tess_children() {
    case $1 in
        '') _tess_r='convert info list get find diff deps init validate rename remove move bpa set add translations perspective script lint format connect query deploy data refresh test completion' ;;
        'bpa') _tess_r='rules' ;;
        'bpa rules') _tess_r='list show add remove ignore unignore' ;;
        'translations') _tess_r='export import cultures' ;;
        'perspective') _tess_r='add remove list' ;;
        'script') _tess_r='export apply' ;;
        'data') _tess_r='init check info embed' ;;
        'test') _tess_r='run init snapshot compare list' ;;
        *) _tess_r='' ;;
    esac
}

